apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: models
spec:
  # Layout and LaTeX-OCR models, downloaded on first use.
  accessModes: [ReadWriteOnce]
  resources: {requests: {storage: 10Gi}}
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: analyzer
  labels: {app.kubernetes.io/name: analyzer, app.kubernetes.io/part-of: elvira}
spec:
  replicas: 1
  strategy: {type: Recreate}
  selector:
    matchLabels: {app.kubernetes.io/name: analyzer}
  template:
    metadata:
      labels: {app.kubernetes.io/name: analyzer, app.kubernetes.io/part-of: elvira}
    spec:
      nodeSelector: {kubernetes.io/arch: amd64}
      containers:
        - name: analyzer
          image: ghcr.io/evilflowerscatalog/evilflowers-analyzer-service:develop
          args: [celery, -A, evilflowers_analyzer.worker, worker, --loglevel=INFO, -E, --concurrency=1, --queues=evilflowers_analyzer, --hostname=analyzer@%h]
          env:
            - name: REDIS_URL
              valueFrom: {secretKeyRef: {name: elvira-env, key: CELERY_BROKER_URL}}
            - name: CATALOG_API_KEY
              valueFrom: {secretKeyRef: {name: elvira-env, key: EXTRACTION_API_KEY}}
            - {name: STORAGE_PATH, value: /var/local/evilflowers}
            - {name: CATALOG_API_URL, value: "http://evilflowers:8000"}
            - {name: BROKER_VISIBILITY_TIMEOUT, value: "43200"}
            - {name: HF_HOME, value: /models}
            - {name: LAYOUT_THREADS, value: "2"}
            - {name: OMP_NUM_THREADS, value: "2"}
            - {name: LAYOUT_BATCH_PAGES, value: "8"}
          volumeMounts:
            - {name: data, mountPath: /var/local/evilflowers}
            - {name: models, mountPath: /models}
            - {name: tmp, mountPath: /tmp}
      volumes:
        - name: data
          persistentVolumeClaim: {claimName: data}
