files.k8s/components/ocr/ocr.yaml:
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ocr
  labels: {app.kubernetes.io/name: ocr, app.kubernetes.io/part-of: elvira}
spec:
  replicas: 1
  strategy: {type: Recreate}
  selector:
    matchLabels: {app.kubernetes.io/name: ocr}
  template:
    metadata:
      labels: {app.kubernetes.io/name: ocr, app.kubernetes.io/part-of: elvira}
    spec:
      terminationGracePeriodSeconds: 30
      nodeSelector: {kubernetes.io/arch: amd64}
      containers:
        - name: ocr
          image: ghcr.io/evilflowerscatalog/evilflowers-ocr-service:master
          args: [celery, -A, evilflowers_ocr_worker.worker, worker, --loglevel=INFO, -E, --concurrency=1, --queues=evilflowers_ocr_worker, --hostname=ocr@%h]
          # Creates <entry>/ocr/ inside directories the catalog (root) owns.
          securityContext: {runAsUser: 0, runAsGroup: 0}
          env:
            - name: BROKER
              valueFrom: {secretKeyRef: {name: elvira-env, key: CELERY_BROKER_URL}}
            - {name: STORAGE_PATH, value: /var/local/evilflowers}
            - {name: BROKER_VISIBILITY_TIMEOUT, value: "43200"}
            - {name: OCR_JOBS, value: "2"}
          volumeMounts:
            - {name: data, mountPath: /var/local/evilflowers}
            - {name: tmp, mountPath: /tmp}
      volumes:
        - name: data
          persistentVolumeClaim: {claimName: data}
        - name: tmp
          emptyDir: {}
